    ]

    SCREEN_RESOLUTIONS = [
        {"width": 1920, "height": 1080},
        {"width": 1366, "height": 768},
        {"width": 1440, "height": 900},
    ]

    TIMEZONES = ["America/New_York", "Europe/London", "Europe/Berlin"]
