    @staticmethod
    def get_random_profile() -> Dict:
        resolution = random.choice(DeviceFingerprintRandomizer.SCREEN_RESOLUTIONS)
        return {
            "user_agent": random.choice(DeviceFingerprintRandomizer.USER_AGENTS),
            "viewport": resolution,
            "screen": resolution,
            "timezone_id": random.choice(DeviceFingerprintRandomizer.TIMEZONES),
            "locale": random.choice(DeviceFingerprintRandomizer.LOCALES),
            "has_touch": random.choice([True, False]),
            "color_scheme": random.choice(["light", "dark"]),
        }

class TorCrawler:
    def __init__(self, tor_config: TorProxyConfig, output_dir: str = "dark_web_data"):
        self.tor_config = tor_config
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(exist_ok=True, parents=True)
        self.visited_urls: Set[str] = set()

    async def create_context(self, browser: Browser) -> BrowserContext:
        profile = DeviceFingerprintRandomizer.get_random_profile()

        context = await browser.new_context(
            proxy={"server": self.tor_config.proxy_url},
            user_agent=profile["user_agent"],
            viewport=profile["viewport"],
            screen=profile["screen"],
            timezone_id=profile["timezone_id"],
            locale=profile["locale"],
            has_touch=profile["has_touch"],
            color_scheme=profile["color_scheme"],
        )
        return context

    async def crawl_url(self, url: str, max_depth: int = 3, current_depth: int = 0) -> List[Dict]:
        if current_depth > max_depth or url in self.visited_urls:
            return []

        self.visited_urls.add(url)
        async with async_playwright() as p:
            browser = await p.firefox.launch()
            context = await self.create_context(browser)
            page = await context.new_page()
            await page.goto(url)
            content = await page.content()
            title = await page.title()
            links = await page.eval_on_selector_all("a", "els => els.map(el => el.href)")
            await browser.close()

        result = {"url": url, "title": title, "content": content[:5000]}
        sub_results = []
        for link in links[:10]:
            if link.startswith("http"):
                sub_results.extend(await self.crawl_url(link, max_depth, current_depth + 1))

        result["sub_pages"] = sub_results
        return [result] + sub_results

