        job.updated_at = datetime.now().isoformat()
        await self.broadcast_update(job.job_id)

        try:
            sub_agents = [
                {"id": "search_agent", "role": "semantic_search", "status": "active", "progress": 0},
                {"id": "contents_agent", "role": "content_extraction", "status": "active", "progress": 0},
                {"id": "similarity_agent", "role": "similar_sources", "status": "active", "progress": 0},
                {"id": "webset_agent", "role": "structured_collection", "status": "active", "progress": 0},
                {"id": "answer_agent", "role": "direct_answers", "status": "active", "progress": 0},
                {"id": "research_agent", "role": "deep_research", "status": "active", "progress": 0},
                {"id": "synthesis_agent", "role": "report_generation", "status": "pending", "progress": 0},
            ]
            job.sub_agents = sub_agents

            search_results = await self.exa_client.search(
                query=job.prompt,
                num_results=1000,
                start_published_date=job.start_date,
                end_published_date=job.end_date,
