            job.current_step = "Tartalom kinyerése"
            contents = await self.exa_client.get_contents([s["id"] for s in search_results.get("results", [])[:500]], text=True, highlights=True, summaries=True)
            for source in job.sources:
                content_id = next((c["id"] for c in contents.get("contents", []) if c["id"] == source.url), None)
                if content_id:
                    source.excerpt += f"\n{contents['contents'][content_id]['text'][:1000]}"

            job.progress = 0.5
            job.current_step = "Hasonló források keresése"
            if job.sources:
                top_url = job.sources[0].url
                similar = await self.exa_client.find_similar(top_url, num_results=200)
                job.similar_links = [{"title": s["title"], "url": s["url"]} for s in similar.get("results", [])]

            job.progress = 0.6
