class VerificationRuntime:
    def __init__(self, lib_path: str = "./libverification.so"):
        self.available = False
        if os.path.exists(lib_path):
            try:
                import ctypes
                self.lib = ctypes.CDLL(lib_path)
                self.lib.verifyJobState.argtypes = [ctypes.c_char_p]
                self.lib.verifyJobState.restype = ctypes.c_bool
                self.lib.checkProgress.argtypes = [ctypes.c_float]
                self.lib.checkProgress.restype = ctypes.c_bool
                self.available = True
            except:
                self.available = False

    def verify_job_state(self, job_data: Dict[str, Any]) -> bool:
        if not self.available:
            return True
        json_str = json.dumps(job_data).encode('utf-8')
        return self.lib.verifyJobState(json_str)

    def check_progress_invariant(self, progress: float) -> bool:
        if not self.available:
            return True
        import ctypes
        return self.lib.checkProgress(ctypes.c_float(progress))

    def verify_sources_validity(self, sources: list) -> bool:
        if not self.available:
            return True
        for source in sources:
            if not source.get('url') or len(source['url']) == 0:
                return False
            if not source.get('title') or len(source['title']) == 0:
                return False
        return True

