class DocumentProcessor:
    def __init__(self):
        self.supported_image_formats = {'.png', '.jpg', '.jpeg', '.tiff', '.bmp', '.gif'}
        self.supported_pdf_formats = {'.pdf'}

    def process_file(self, file_path: Path) -> Dict[str, str]:
        suffix = file_path.suffix.lower()

        if suffix in self.supported_image_formats:
            return self.process_image(file_path)
        elif suffix in self.supported_pdf_formats:
            return self.process_pdf(file_path)
        else:
            raise ValueError(f"Unsupported file format: {suffix}")

    def process_image(self, image_path: Path) -> Dict[str, str]:
        try:
            image = Image.open(image_path)
            text = pytesseract.image_to_string(image, lang='hun+eng')
            ocr_data = pytesseract.image_to_data(image, lang='hun+eng', output_type=pytesseract.Output.DICT)

            confidences = [int(conf) for conf in ocr_data['conf'] if int(conf) > 0]
            avg_confidence = sum(confidences) / len(confidences) if confidences else 0.0

            return {
                "text": text,
                "word_count": len(text.split()),
                "confidence": avg_confidence,
                "language": "hun+eng",
                "method": "tesseract_ocr"
            }
        except Exception as e:
            raise

    def process_pdf(self, pdf_path: Path) -> Dict[str, str]:
        try:
            doc = fitz.open(pdf_path)

            full_text = []
            metadata = {
                "page_count": len(doc),
                "title": doc.metadata.get("title", ""),
                "author": doc.metadata.get("author", ""),
                "subject": doc.metadata.get("subject", ""),
                "keywords": doc.metadata.get("keywords", ""),
            }

            for page_num in range(len(doc)):
                page = doc[page_num]
                text = page.get_text()
                full_text.append(text)

            combined_text = "\n\n".join(full_text)

            return {
                "text": combined_text,
                "page_count": len(doc),
                "word_count": len(combined_text.split()),
                "metadata": metadata,
                "method": "pymupdf_extraction"
            }
        except Exception as e:
            raise
        finally:
            if 'doc' in locals():
                doc.close()

class MinHashDeduplicator:
    def __init__(self, threshold: float = 0.8, num_perm: int = 128):
        self.threshold = threshold
        self.num_perm = num_perm
        self.lsh = MinHashLSH(threshold=threshold, num_perm=num_perm)
        self.seen_hashes: Dict[str, MinHash] = {}

    def is_duplicate(self, doc_id: str, text: str) -> bool:
        minhash = self._compute_minhash(text)
        similar = self.lsh.query(minhash)

        if similar:
            return True

        self.lsh.insert(doc_id, minhash)
        self.seen_hashes[doc_id] = minhash
        return False

    def _compute_minhash(self, text: str) -> MinHash:
        minhash = MinHash(num_perm=self.num_perm)
        tokens = text.lower().split()
        for token in tokens:
            minhash.update(token.encode('utf-8'))
        return minhash

class TemporalTopicDivergence:
    def __init__(self, window_size: int = 100, divergence_threshold: float = 0.5):
        self.window_size = window_size
        self.threshold = divergence_threshold
        self.topic_history: List[Dict[str, float]] = []

    def add_document_topics(self, topics: Dict[str, float]):
        self.topic_history.append(topics)
        if len(self.topic_history) > self.window_size * 2:
            self.topic_history.pop(0)

    def detect_shift(self) -> Tuple[bool, float]:
        if len(self.topic_history) < self.window_size * 2:
            return False, 0.0

        recent = self.topic_history[-self.window_size:]
        previous = self.topic_history[-self.window_size*2:-self.window_size]

        recent_dist = self._aggregate_distribution(recent)
        previous_dist = self._aggregate_distribution(previous)

        kl_div = self._kl_divergence(previous_dist, recent_dist)

        is_shift = kl_div > self.threshold

        return is_shift, kl_div

    def _aggregate_distribution(self, topic_list: List[Dict[str, float]]) -> np.ndarray:
        all_topics = set()
        for topics in topic_list:
            all_topics.update(topics.keys())

        topic_index = {topic: i for i, topic in enumerate(sorted(all_topics))}
        dist = np.zeros(len(topic_index))

        for topics in topic_list:
            for topic, prob in topics.items():
                dist[topic_index[topic]] += prob

        dist = dist / (dist.sum() + 1e-10)
        return dist

    def _kl_divergence(self, p: np.ndarray, q: np.ndarray) -> float:
        p = p + 1e-10
        q = q + 1e-10
        p = p / p.sum()
        q = q / q.sum()
        return entropy(p, q)

class EntityGraphNoveltyDetector:
    def __init__(self):
        self.entities: Set[str] = set()
        self.edges: Set[Tuple[str, str, str]] = set()

    def add_entity(self, entity: str):
        self.entities.add(entity)

    def add_edge(self, entity1: str, relation: str, entity2: str) -> bool:
        edge = (entity1, relation, entity2)

        if edge in self.edges:
            return False

        self.edges.add(edge)
        self.entities.add(entity1)
        self.entities.add(entity2)

        return True

    def get_entity_degree(self, entity: str) -> int:
        degree = 0
        for e1, _, e2 in self.edges:
            if e1 == entity or e2 == entity:
                degree += 1
        return degree

class NoveltyPipeline:
    def __init__(self, output_dir: str = "novelty_data"):
        self.deduplicator = MinHashDeduplicator()
        self.topic_divergence = TemporalTopicDivergence()
        self.entity_graph = EntityGraphNoveltyDetector()
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(exist_ok=True, parents=True)
        self.novel_docs: List[Dict] = []

    def process_document(self, doc_id: str, text: str, topics: Dict[str, float],
                        entities: List[Tuple[str, str, str]]) -> Dict:
        result = {
            "doc_id": doc_id,
            "is_duplicate": False,
            "topic_shift": False,
            "new_edges": 0,
            "novelty_score": 0.0,
        }

        if self.deduplicator.is_duplicate(doc_id, text):
            result["is_duplicate"] = True
            result["novelty_score"] = 0.0
            return result

        self.topic_divergence.add_document_topics(topics)
        topic_shift, kl_div = self.topic_divergence.detect_shift()
        result["topic_shift"] = topic_shift
        result["kl_divergence"] = kl_div

        new_edges = 0
        for e1, relation, e2 in entities:
            if self.entity_graph.add_edge(e1, relation, e2):
                new_edges += 1
        result["new_edges"] = new_edges

        novelty_score = 0.0
        if not result["is_duplicate"]:
            novelty_score += 0.3
        if topic_shift:
            novelty_score += 0.3
        novelty_score += min(new_edges * 0.1, 0.4)

        result["novelty_score"] = novelty_score

        if novelty_score > 0.5:
            self.novel_docs.append({"doc_id": doc_id, "score": novelty_score})

        return result

@dataclass
class Entity:
    entity_id: str
    entity_type: str
    attributes: Dict[str, str] = field(default_factory=dict)
    aliases: Set[str] = field(default_factory=set)

@dataclass
class Relation:
    source_id: str
    target_id: str
    relation_type: str
    confidence: float
    timestamp: float
    metadata: Dict = field(default_factory=dict)

class KnowledgeGraph:
    def __init__(self, pinecone_index_name: str = "knowledge-graph", graph_file: Optional[str] = None):
        self.graph = nx.MultiDiGraph()
        self.entities: Dict[str, Entity] = {}
        self.graph_file = Path(graph_file) if graph_file else Path("knowledge_graph.json")
        self.pc = pinecone.Pinecone(api_key=os.getenv("PINECONE_API_KEY"))
        self.index_name = pinecone_index_name
        if pinecone_index_name not in self.pc.list_indexes().names():
            self.pc.create_index(
                name=pinecone_index_name,
                dimension=1536,
                metric="cosine",
                spec=ServerlessSpec(cloud="aws", region="us-east-1")
            )
        self.pinecone_index = self.pc.Index(pinecone_index_name)

        if self.graph_file.exists():
            self.load()

    def add_entity(self, entity: Entity):
        self.entities[entity.entity_id] = entity
        self.graph.add_node(entity.entity_id, **entity.attributes, type=entity.entity_type)
        embedding = np.random.rand(1536).tolist()  
        self.pinecone_index.upsert(vectors=[(entity.entity_id, embedding, {"type": entity.entity_type})])

    def add_relation(self, relation: Relation):
        if relation.source_id not in self.entities:
            return
        if relation.target_id not in self.entities:
            return

        self.graph.add_edge(
            relation.source_id,
            relation.target_id,
            key=relation.relation_type,
            type=relation.relation_type,
            confidence=relation.confidence,
            timestamp=relation.timestamp,
            **relation.metadata
        )

    def predict_links(self, entity_id: str, top_k: int = 10) -> List[Tuple[str, float]]:
        if entity_id not in self.graph:
            return []

        candidates = []
        existing_neighbors = set(self.graph.successors(entity_id)) | set(self.graph.predecessors(entity_id))

        for node in self.graph.nodes():
            if node == entity_id or node in existing_neighbors:
                continue

            node_neighbors = set(self.graph.successors(node)) | set(self.graph.predecessors(node))
            common = len(existing_neighbors & node_neighbors)

            degree_product = self.graph.degree(entity_id) * self.graph.degree(node)

            score = common * 0.6 + np.log1p(degree_product) * 0.4

            if score > 0:
                candidates.append((node, score))

        candidates.sort(key=lambda x: x[1], reverse=True)

        return candidates[:top_k]

    def prioritize_leads(self) -> List[Tuple[str, float]]:
        if not self.graph.nodes():
            return []

        try:
            betweenness = nx.betweenness_centrality(self.graph)
            pagerank = nx.pagerank(self.graph)
        except:
            betweenness = {node: 0.0 for node in self.graph.nodes()}
            pagerank = {node: 1.0 / len(self.graph.nodes()) for node in self.graph.nodes()}

        lead_scores = []
        for node in self.graph.nodes():
            degree = self.graph.degree(node)
            score = (betweenness.get(node, 0) * 0.4 +
                    pagerank.get(node, 0) * 0.3 +
                    np.log1p(degree) * 0.3)
            lead_scores.append((node, score))

        lead_scores.sort(key=lambda x: x[1], reverse=True)

        return lead_scores

    def save(self):
        data = {
            "entities": [
                {
                    "entity_id": e.entity_id,
                    "entity_type": e.entity_type,
                    "attributes": e.attributes,
                    "aliases": list(e.aliases),
                }
                for e in self.entities.values()
            ],
            "edges": [
                {
                    "source": u,
                    "target": v,
                    "type": data.get('type'),
                    "confidence": data.get('confidence'),
                    "timestamp": data.get('timestamp'),
                    "metadata": {k: v for k, v in data.items() if k not in ['type', 'confidence', 'timestamp']},
                }
                for u, v, data in self.graph.edges(data=True)
            ],
        }

        self.graph_file.write_text(json.dumps(data, indent=2), encoding='utf-8')

    def load(self):
        data = json.loads(self.graph_file.read_text(encoding='utf-8'))

        for e_data in data.get("entities", []):
            entity = Entity(
                entity_id=e_data["entity_id"],
                entity_type=e_data["entity_type"],
                attributes=e_data.get("attributes", {}),
                aliases=set(e_data.get("aliases", [])),
            )
            self.add_entity(entity)

        for edge_data in data.get("edges", []):
            relation = Relation(
                source_id=edge_data["source"],
                target_id=edge_data["target"],
                relation_type=edge_data["type"],
                confidence=edge_data.get("confidence", 0.5),
                timestamp=edge_data.get("timestamp", 0.0),
                metadata=edge_data.get("metadata", {}),
            )
            self.add_relation(relation)

