class CerebrasClient:
    def __init__(self, api_key: str):
        self.client = Cerebras(api_key=api_key)

    async def generate_synthesis(self, prompt: str, model: str = "gpt-oss-120b", max_tokens: int = 65000) -> str:
        response = await asyncio.get_event_loop().run_in_executor(
            None,
            lambda: self.client.chat.completions.create(
                model=model,
                messages=[{"role": "user", "content": prompt}],
                max_tokens=max_tokens,
                temperature=0.7
            )
        )
        return response.choices[0].message.content

class GrokClient:
    def __init__(self, api_key: str):
        self.client = Grok(api_key=api_key)

    async def generate(self, prompt: str, model: str = "grok-4", max_tokens: int = 128000, stream: bool = False) -> str:
        response = await asyncio.get_event_loop().run_in_executor(
            None,
            lambda: self.client.chat.completions.create(
                model=model,
                messages=[{"role": "user", "content": prompt}],
                max_tokens=max_tokens,
                stream=stream,
                temperature=0.7
            )
        )
        if stream:
            full_text = ""
            for chunk in response:
                full_text += chunk.choices[0].delta.content or ""
            return full_text
        return response.choices[0].message.content

