class MultiAgentOrchestrator:
    def __init__(self):
        self.exa_client = ExaClient(os.getenv("EXA_API_KEY"))
        self.cerebras_client = CerebrasClient(os.getenv("CEREBRAS_API_KEY"))
        self.grok_client = GrokClient(os.getenv("XAI_API_KEY"))
        self.knowledge_graph = KnowledgeGraph()
        self.novelty_pipeline = NoveltyPipeline()
        self.task_store: Dict[str, Dict[str, TaskState]] = defaultdict(dict)
        self.reasoning_stream: List[ReasoningEvent] = []
        self.jobs_db: Dict[str, JobState] = {}
        self.websocket_connections: Set[WebSocket] = set()
        self.tor_crawler = TorCrawler(TorProxyConfig())

    async def execute_enhanced_research(self, job: JobState):
        job.status = JobStatus.RUNNING
        job.progress = 0.1
        job.current_step = "Kutatás inicializálása"
        job.updated_at = datetime.now().isoformat()
        await self.broadcast_update(job.job_id)

        try:
            sub_agents = [
                {"id": "search_agent", "role": "semantic_search", "status": "active", "progress": 0},
                {"id": "contents_agent", "role": "content_extraction", "status": "active", "progress": 0},
                {"id": "similarity_agent", "role": "similar_sources", "status": "active", "progress": 0},
                {"id": "webset_agent", "role": "structured_collection", "status": "active", "progress": 0},
                {"id": "answer_agent", "role": "direct_answers", "status": "active", "progress": 0},
                {"id": "research_agent", "role": "deep_research", "status": "active", "progress": 0},
                {"id": "synthesis_agent", "role": "report_generation", "status": "pending", "progress": 0},
            ]
            job.sub_agents = sub_agents

            search_results = await self.exa_client.search(
                query=job.prompt,
                num_results=1000,
                start_published_date=job.start_date,
                end_published_date=job.end_date,
                include_domains=job.include_domains,
                exclude_domains=job.exclude_domains
            )
            job.sources = [Source(url=s["url"], title=s["title"], date=s.get("published_date"), excerpt=s.get("text", "")[:300]) for s in search_results.get("results", [])[:1000]]

            job.progress = 0.3
            job.current_step = "Tartalom kinyerése"
            contents = await self.exa_client.get_contents([s["id"] for s in search_results.get("results", [])[:500]], text=True, highlights=True, summaries=True)
            for source in job.sources:
                content_id = next((c["id"] for c in contents.get("contents", []) if c["id"] == source.url), None)
                if content_id:
                    source.excerpt += f"\n{contents['contents'][content_id]['text'][:1000]}"

            job.progress = 0.5
            job.current_step = "Hasonló források keresése"
            if job.sources:
                top_url = job.sources[0].url
                similar = await self.exa_client.find_similar(top_url, num_results=200)
                job.similar_links = [{"title": s["title"], "url": s["url"]} for s in similar.get("results", [])]

            job.progress = 0.6
            job.current_step = "Webset építése"
            webset = await self.exa_client.create_webset(name=f"Research_{job.job_id}", description=job.prompt)
            webset_id = webset["webset_id"]
            await self.exa_client.add_search_to_webset(webset_id, job.prompt, num_results=1000)
            items = await self.exa_client.get_webset_items(webset_id, limit=1000)
            job.webset_items = [{"title": i["title"], "url": i["url"], "category": i.get("category", "")} for i in items.get("items", [])]

            job.progress = 0.7
            job.current_step = "Mély kutatás"
            deep_research = await self.exa_client.research(job.prompt, max_results=2000, include_domains=job.include_domains, exclude_domains=job.exclude_domains, start_published_date=job.start_date, end_published_date=job.end_date)
            job.sources.extend([Source(url=s["url"], title=s["title"], date=s.get("published_date"), excerpt=s.get("answer", "")) for s in deep_research.get("research", {}).get("citations", [])])

            job.progress = 0.8
            job.current_step = "Direkt válaszok"
            answers = await self.exa_client.answer(job.prompt, text=True)
            job.report = answers.get("answer", "")

            job.progress = 0.9
            job.current_step = "Szintézis generálása"
            context = "\n\n".join([f"{s.title}: {s.excerpt}" for s in job.sources[:50]])
            synthesis_prompt = f"Készíts 30-40 oldalas átfogó jelentést a következő kérdés alapján:\n{job.prompt}\nKontextus:\n{context}"
            synthesis = await self.cerebras_client.generate_synthesis(synthesis_prompt, max_tokens=128000)
            grok_synthesis = await self.grok_client.generate(synthesis_prompt, model="grok-4", max_tokens=128000)
            job.report = f"{synthesis}\n\nGrok kiegészítés:\n{grok_synthesis}"

            job.progress = 1.0
            job.status = JobStatus.COMPLETED
            job.current_step = "Kész"
            job.updated_at = datetime.now().isoformat()

            dark_web_sources = await self.tor_crawler.crawl_url("", max_depth=2)
            job.sources.extend([Source(url=s["url"], title=s["title"], excerpt=s["content"]) for s in dark_web_sources])

            self.knowledge_graph.add_entities_from_sources(job.sources)
            self.novelty_pipeline.process_sources(job.sources)

        except Exception as e:
            job.status = JobStatus.FAILED
            job.error = str(e)
            job.updated_at = datetime.now().isoformat()
            logger.error(f"Enhanced research error: {e}")

        await self.broadcast_update(job.job_id)

    async def handle_websocket_message(self, job_id: str, message: Dict):
        job = self.jobs_db.get(job_id)
        if not job:
            return
        if message.get("type") == "update_query":
            job.prompt += f"\nFrissítés: {message.get('content')}"
            await self.execute_enhanced_research(job)

    async def broadcast_update(self, job_id: str):
        job = self.jobs_db.get(job_id)
        if job:
            update = {
                "job_id": job.job_id,
                "status": job.status.value,
                "progress": job.progress,
                "current_step": job.current_step,
                "sub_agents": job.sub_agents,
                "sources_count": len(job.sources),
                "report_snippet": job.report[:500] if job.report else ""
            }
            disconnected = set()
            for connection in self.websocket_connections:
                try:
                    await connection.send_json(update)
                except WebSocketDisconnect:
                    disconnected.add(connection)
            self.websocket_connections -= disconnected

