@app.on_event("startup")
async def startup_event():
    Path("logs").mkdir(exist_ok=True)
    Path("cache").mkdir(exist_ok=True)
    Path("reports").mkdir(exist_ok=True)
    Path("uploads").mkdir(exist_ok=True)
    Path("static").mkdir(exist_ok=True)
    logger.info("Application directories initialized")

@app.websocket("/ws/{job_id}")
async def websocket_endpoint(websocket: WebSocket, job_id: str):
    await websocket.accept()
    orchestrator.websocket_connections.add(websocket)
    try:
        while True:
            data = await websocket.receive_json()
            await orchestrator.handle_websocket_message(job_id, data)
    except WebSocketDisconnect:
        orchestrator.websocket_connections.remove(websocket)

@app.post("/query")
async def create_query(request: QueryRequest, background_tasks: BackgroundTasks):
    job_id = hashlib.md5(f"{request.prompt}{time.time()}".encode()).hexdigest()[:16]

    job = JobState(
        job_id=job_id,
        mode=request.mode,
        prompt=request.prompt,
        created_at=datetime.now().isoformat(),
        updated_at=datetime.now().isoformat(),
        time_limit_minutes=request.time_limit_minutes,
        attached_files=request.attached_files,
        start_date=request.start_date,
        end_date=request.end_date,
        include_domains=request.include_domains,
        exclude_domains=request.exclude_domains
    )

    orchestrator.jobs_db[job_id] = job

    background_tasks.add_task(orchestrator.execute_enhanced_research, job)

    logger.info(f"Job created: {job_id} - Mode: {request.mode.value}")

    return {"job_id": job_id, "status": "created", "mode": request.mode.value}

@app.post("/upload")
async def upload_file(file: UploadFile = File(...)):
    try:
        file_id = hashlib.md5(f"{file.filename}{time.time()}".encode()).hexdigest()[:16]
        file_path = Path(f"uploads/{file_id}_{file.filename}")
        file_path.parent.mkdir(exist_ok=True)

        with open(file_path, "wb") as f:
            content = await file.read()
            f.write(content)

        logger.info(f"File uploaded: {file.filename}")

        return {
            "file_id": file_id,
            "filename": file.filename,
            "size": len(content),
            "path": str(file_path)
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/status/{job_id}")
async def get_status(job_id: str):
    if job_id not in orchestrator.jobs_db:
        raise HTTPException(status_code=404, detail="Job not found")

    job = orchestrator.jobs_db[job_id]

    return {
        "job_id": job.job_id,
        "status": job.status.value,
        "mode": job.mode.value,
        "progress": job.progress,
        "current_step": job.current_step,
        "error": job.error,
        "sub_agents": job.sub_agents,
        "sources_count": len(job.sources),
        "webset_count": len(job.webset_items),
        "similar_links_count": len(job.similar_links)
    }

